{"success":true,"response":{"exitCode":0,"result":"     1	import type { TrueForgeApi } from "@truefoundry/trueforge-sdk";
     2	
     3	/**
     4	 * Pure timeline logic for the case file UI. Maps live harness events onto the
     5	 * eight protocol stages from skills/rarecase-debugging/SKILL.md. No React here,
     6	 * so the mapping is unit-testable against a recorded case.
     7	 *
     8	 * Stages are assigned by a cursor, not by event type. The protocol is a
     9	 * sequence, and the agent announces each stage as it enters it; work that
    10	 * follows belongs to whichever stage is open. This is the only way Hypothesis
    11	 * and Diagnosis can ever be populated — they run no tools — and it is also the
    12	 * only way to tell a Reproduction test run from a Verification one, since both
    13	 * are the same `exec` call against the same sandbox.
    14	 */
    15	
    16	export const STAGES = [
    17	  "Evidence",
    18	  "Hypothesis",
    19	  "Reproduction",
    20	  "Diagnosis",
    21	  "Patch",
    22	  "Verification",
    23	  "Approval",
    24	  "Receipt",
    25	] as const;
    26	
    27	export type Stage = (typeof STAGES)[number];
    28	
    29	export interface TimelineEntry {
    30	  /** Stable identity: coalesced updates replace the entry instead of appending. */
    31	  key: string;
    32	  /** The protocol stage this belongs to, or null for the raw event log. */
    33	  stage: Stage | null;
    34	  kind: "message" | "event" | "tool";
    35	  title: string;
    36	  text: string;
    37	  /** What the entry is actually about, in the agent's own words where it gave them. */
    38	  detail?: string;
    39	  /** A tool call whose response has come back. */
    40	  settled?: boolean;
    41	}
    42	
    43	/**
    44	 * The agent writes its stage transitions into its narration. Left to itself it
    45	 * drifts — one run produced `**Stage 1: Evidence**`, the next
    46	 * `**Stage 1 — Evidence**` from the same instructions — so the skill mandates a
    47	 * literal form and this tolerates the separators observed in practice.
    48	 */
    49	const STAGE_MARKER = /\*\*Stage\s*(\d)\s*[:—–-]\s*([A-Za-z]+)\s*\*\*/g;
    50	
    51	export function findStageMarker(text: string): Stage | null {
    52	  let found: Stage | null = null;
    53	  STAGE_MARKER.lastIndex = 0;
    54	  for (const match of text.matchAll(STAGE_MARKER)) {
    55	    const byNumber = STAGES[Number(match[1]) - 1];
    56	    const named = STAGES.find((stage) => stage.toLowerCase() === match[2]?.toLowerCase());
    57	    // The name wins over the number: a model that miscounts is still telling
    58	    // you which stage it believes it is in.
    59	    const stage = named ?? byNumber;
    60	    if (stage) {
    61	      found = stage;
    62	    }
    63	  }
    64	  return found;
    65	}
    66	
    67	/** Removes the stage markers from text on its way to the screen. */
    68	export function stripStageMarkers(text: string): string {
    69	  return text
    70	    .replace(STAGE_MARKER, "")
    71	    .replace(/[ \t]{2,}/g, " ")
    72	    .trimStart();
    73	}
    74	
    75	/** Message content arrives as plain text or structured parts; flatten both. */
    76	export function contentToText(content: TrueForgeApi.ModelMessageEvent["content"]): string {
    77	  if (content == null) {
    78	    return "";
    79	  }
    80	  if (typeof content === "string") {
    81	    return content;
    82	  }
    83	  return content
    84	    .map((part) => ("text" in part && typeof part.text === "string" ? part.text : ""))
    85	    .join("");
    86	}
    87	
    88	export interface ToolCallSummary {
    89	  name: string;
    90	  server?: string;
    91	  argsJson?: string;
    92	  /** The agent's own one-line reason for the call, when it supplied one. */
    93	  intent?: string;
    94	}
    95	
    96	/**
    97	 * Names the action a tool call performs. Three shapes have been observed on the
    98	 * wire, so all three are handled: `toolInfo` carries the resolved name and
    99	 * server and is preferred; some calls arrive wrapped in the harness's own
   100	 * `call_tool` envelope with the real action inside the arguments; and the rest
   101	 * are named directly on the function. Streamed arguments can still be truncated
   102	 * JSON when a turn ends early, so parsing never decides whether there is a name.
   103	 */
   104	export function describeToolCall(call: TrueForgeApi.ToolCall): ToolCallSummary {
   105	  const info = (call as { toolInfo?: { name?: unknown; serverName?: unknown } }).toolInfo;
   106	  const raw = call.function.arguments;
   107	
   108	  const summary: ToolCallSummary = {
   109	    name: typeof info?.name === "string" ? info.name : call.function.name,
   110	    server: typeof info?.serverName === "string" ? info.serverName : undefined,
   111	    argsJson: raw || undefined,
   112	  };
   113	
   114	  try {
   115	    const parsed: unknown = JSON.parse(raw);
   116	    if (parsed && typeof parsed === "object") {
   117	      const fields = parsed as {
   118	        tool_name?: unknown;
   119	        mcp_server?: unknown;
   120	        input?: unknown;
   121	        intent?: unknown;
   122	      };
   123	      // The wrapper: the name on the call is `call_tool` and the action the
   124	      // human would be approving sits inside the arguments.
   125	      if (typeof fields.tool_name === "string") {
   126	        summary.name = fields.tool_name;
   127	        summary.server = typeof fields.mcp_server === "string" ? fields.mcp_server : summary.server;
   128	        summary.argsJson = JSON.stringify(fields.input ?? {}, null, 2);
   129	      } else {
   130	        summary.argsJson = JSON.stringify(parsed, null, 2);
   131	      }
   132	      if (typeof fields.intent === "string") {
   133	        summary.intent = fields.intent;
   134	      }
   135	    }
   136	  } catch {
   137	    // Not JSON, or not finished streaming: show what we do have.
   138	  }
   139	
   140	  return summary;
   141	}
   142	
   143	export interface TimelineState {
   144	  entries: TimelineEntry[];
   145	  /** The stage the agent last announced. Null until it announces its first. */
   146	  stage: Stage | null;
   147	  /** Tool call id to the entry key it created, so a response can settle it. */
   148	  pendingCalls: Record<string, string>;
   149	  /** Assembled text per message id, so a marker split across deltas is still seen. */
   150	  messageText: Record<string, string>;
   151	}
   152	
   153	export function emptyTimeline(): TimelineState {
   154	  return { entries: [], stage: null, pendingCalls: {}, messageText: {} };
   155	}
   156	
   157	function upsert(entries: TimelineEntry[], next: TimelineEntry): TimelineEntry[] {
   158	  const index = entries.findIndex((entry) => entry.key === next.key);
   159	  if (index === -1) {
   160	    return [...entries, next];
   161	  }
   162	  const updated = [...entries];
   163	  updated[index] = next;
   164	  return updated;
   165	}
   166	
   167	/**
   168	 * Only two events name their own stage regardless of what the agent announced:
   169	 * a pause is the approval, and a terminal turn is the receipt. Everything else
   170	 * follows the cursor. `sandbox.created` is deliberately not Reproduction — it
   171	 * fires the first time the agent runs anything at all, which in practice is
   172	 * while it is still reading the issue.
   173	 */
   174	function anchoredStage(type: string): Stage | null {
   175	  if (type === "tool.approval_required") return "Approval";
   176	  if (type === "turn.done") return "Receipt";
   177	  return null;
   178	}
   179	
   180	export function applyEvent(
   181	  state: TimelineState,
   182	  event: TrueForgeApi.TurnStreamingEvent,
   183	): TimelineState {
   184	  if (event.type === "model.message" || event.type === "model.message.delta") {
   185	    const key = `msg:${event.id}`;
   186	    const fragment =
   187	      event.type === "model.message.delta" ? (event.content ?? "") : contentToText(event.content);
   188	    const previous = state.messageText[event.id] ?? "";
   189	    // A base message re-yielded with its assembled content replaces what the
   190	    // deltas built; a delta appends. Longest wins, so either order converges.
   191	    const text =
   192	      event.type === "model.message" && fragment.length >= previous.length
   193	        ? fragment
   194	        : previous + fragment;
   195	
   196	    const stage = findStageMarker(text) ?? state.stage;
   197	    let entries = upsert(state.entries, {
   198	      key,
   199	      stage,
   200	      kind: "message",
   201	      title: "Agent",
   202	      // The marker is addressed to the case file, not to the reader: the stage
   203	      // it names is already the heading the text sits under.
   204	      text: stripStageMarkers(text),
   205	    });
   206	    const pendingCalls = { ...state.pendingCalls };
   207	
   208	    if (event.type === "model.message" && event.toolCalls) {
   209	      for (const call of event.toolCalls) {
   210	        const summary = describeToolCall(call);
   211	        const callKey = `tool:${call.id}`;
   212	        pendingCalls[call.id] = callKey;
   213	        entries = upsert(entries, {
   214	          key: callKey,
   215	          stage,
   216	          kind: "tool",
   217	          title: summary.server ? `${summary.name} on ${summary.server}` : summary.name,
   218	          text: "",
   219	          detail: summary.intent ?? summary.argsJson,
   220	        });
   221	      }
   222	    }
   223	
   224	    return {
   225	      entries,
   226	      stage,
   227	      pendingCalls,
   228	      messageText: { ...state.messageText, [event.id]: text },
   229	    };
   230	  }
   231	
   232	  if (event.type === "tool.response") {
   233	    // The response names no tool, only the call it answers, so the only way to
   234	    // know what came back is to find the call that asked.
   235	    const key = state.pendingCalls[event.toolCallId];
   236	    const existing = key ? state.entries.find((entry) => entry.key === key) : undefined;
   237	    if (!existing) {
   238	      return state;
   239	    }
   240	    return { ...state, entries: upsert(state.entries, { ...existing, settled: true }) };
   241	  }
   242	
   243	  return {
   244	    ...state,
   245	    entries: [
   246	      ...state.entries,
   247	      {
   248	        key: `evt:${event.id}`,
   249	        stage: anchoredStage(event.type),
   250	        kind: "event",
   251	        title: event.type,
   252	        text: "",
   253	      },
   254	    ],
   255	  };
   256	}
   257	
   258	export interface PendingApproval {
   259	  threadId: string;
   260	  toolCallId: string;
   261	  sourceEventId?: string;
   262	}
   263	
   264	/**
   265	 * A turn ends in one of three terminal states, and all three arrive as
   266	 * `turn.done`. Only `done` produced a case. An error or a cancellation carries
   267	 * no output, so reading a receipt off it presents a failed run as a finished
   268	 * one — with the agent's last sentence standing in for a result it never
   269	 * reached.
   270	 */
   271	export function terminalFailure(event: TrueForgeApi.TurnDoneEvent): string | null {
   272	  const state = event.state;
   273	  if (state.status === "error") {
   274	    return state.message || "The harness ended the turn with an error.";
   275	  }
   276	  if (state.status === "cancelled") {
   277	    return `The turn was cancelled: ${state.reason}.`;
   278	  }
   279	  return null;
   280	}
   281	
   282	/**
   283	 * A turn that pauses for a human still reports `turn.done`, with the decision
   284	 * it is waiting on listed in `requiredActions`. Treating that as the end of the
   285	 * case would close the approval before it was ever shown.
   286	 */
   287	export function pendingActions(
   288	  event: TrueForgeApi.TurnDoneEvent,
   289	): TrueForgeApi.ActionRequiredEvent[] {
   290	  return "requiredActions" in event.state ? event.state.requiredActions : [];
   291	}
   292	
   293	/** Pulls the decision the human owes out of a pause event, if it is one. */
   294	export function extractApproval(event: TrueForgeApi.TurnStreamingEvent): PendingApproval | null {
   295	  if (event.type !== "tool.approval_required") {
   296	    return null;
   297	  }
   298	  const call = event.toolCalls[0];
   299	  if (!call) {
   300	    return null;
   301	  }
   302	  return {
   303	    threadId: event.threadId,
   304	    toolCallId: call.id,
   305	    sourceEventId: call.sourceEventId,
   306	  };
   307	}
   308	
   309	const PR_URL = /https?:\/\/[^\s)"']+/g;
   310	
   311	export interface CaseReceipt {
   312	  text: string;
   313	  links: string[];
   314	}
   315	
   316	/**
   317	 * The receipt is whatever the final message reports, PR links extracted. A turn
   318	 * can reach a terminal state with no output at all — cancelled, errored, or
   319	 * stopped after a denial — so the caller may supply the last narration it saw
   320	 * rather than close the case on a blank panel.
   321	 */
   322	export function buildReceipt(
   323	  event: TrueForgeApi.TurnDoneEvent,
   324	  fallbackText = "",
   325	): CaseReceipt | null {
   326	  const output = "output" in event.state ? event.state.output : null;
   327	  const text = (contentToText(output?.content ?? null) || fallbackText).trim();
   328	  if (!text) {
   329	    return null;
   330	  }
   331	  return { text, links: text.match(PR_URL) ?? [] };
   332	}
"}}

