     3	import { useCallback, useRef, useState } from "react";
     4	import type { TrueForgeApi } from "@truefoundry/trueforge-sdk";
     5	import { ApprovalCard, type ResolvedPending } from "@/components/approval-card";
     6	import {
     7	  applyEvent,
     8	  buildReceipt,
     9	  contentToText,
    10	  describeToolCall,
    11	  emptyTimeline,
    12	  extractApproval,
    13	  pendingActions,
    14	  terminalFailure,
    15	  STAGES,
    16	  type CaseReceipt,
    17	  type TimelineState,
    18	} from "@/lib/timeline";
    19	
    20	type StreamEvent =
    21	  | { type: "case.started"; sessionId: string }
    22	  | { type: "stream.error"; error: string }
    23	  | TrueForgeApi.TurnStreamingEvent;
    24	
    25	type Phase = "idle" | "running" | "awaiting" | "done" | "error";
    26	
    27	/**
    28	 * Reads an SSE response body and hands each parsed event to `onEvent`.
    29	 * Frames can split across chunks, so bytes buffer until a full `\n\n` boundary.
    30	 */
    31	async function consumeSse(
    32	  response: Response,
    33	  onEvent: (event: StreamEvent) => void,
    34	): Promise<void> {
    35	  if (!response.ok || !response.body) {
    36	    const problem = (await response.json().catch(() => null)) as { error?: string } | null;
    37	    throw new Error(problem?.error ?? `Request failed with status ${response.status}`);
    38	  }
    39	
    40	  const reader = response.body.getReader();
    41	  const decoder = new TextDecoder();
    42	  let buffer = "";
    43	  try {
    44	    for (;;) {
    45	      const { done, value } = await reader.read();
    46	      if (done) {
    47	        break;
    48	      }
    49	      buffer += decoder.decode(value, { stream: true });
    50	      let boundary = buffer.indexOf("\n\n");
    51	      while (boundary !== -1) {
    52	        const frame = buffer.slice(0, boundary);
    53	        buffer = buffer.slice(boundary + 2);
    54	        if (frame.startsWith("data: ")) {
    55	          onEvent(JSON.parse(frame.slice("data: ".length)) as StreamEvent);
    56	        }
    57	        boundary = buffer.indexOf("\n\n");
    58	      }
    59	    }
    60	  } finally {
    61	    reader.releaseLock();
    62	  }
    63	}
    64	
    65	/**
    66	 * The agent narrates in markdown. Only the two marks it actually uses to carry
    67	 * meaning are honoured — emphasis and code — which is a few lines here against
    68	 * a rendering dependency for prose nobody will click.
    69	 */
    70	const INLINE = /(\*\*[^*]+\*\*|`[^`]+`)/g;
    71	
    72	function Narration({ text }: { text: string }) {
    73	  return (
    74	    <>
    75	      {text.split(INLINE).map((piece, index) => {
    76	        if (piece.startsWith("**") && piece.endsWith("**")) {
    77	          return <strong key={index}>{piece.slice(2, -2)}</strong>;
    78	        }
    79	        if (piece.startsWith("`") && piece.endsWith("`") && piece.length > 1) {
    80	          return (
    81	            <code key={index} className="font-mono text-[0.9em] text-sky-700 dark:text-sky-400">
    82	              {piece.slice(1, -1)}
    83	            </code>
    84	          );
    85	        }
    86	        return piece;
    87	      })}
    88	    </>
    89	  );
    90	}
