    92	export function CaseRunner() {
    93	  const [phase, setPhase] = useState<Phase>("idle");
    94	  const [prompt, setPrompt] = useState("");
    95	  const [timeline, setTimeline] = useState<TimelineState>(emptyTimeline);
    96	  const [pending, setPending] = useState<ResolvedPending | null>(null);
    97	  const [deciding, setDeciding] = useState(false);
    98	  const [receipt, setReceipt] = useState<CaseReceipt | null>(null);
    99	  const [error, setError] = useState<string | null>(null);
   100	
   101	  // Tool names and arguments live on the model.message that requested the
   102	  // call; the pause event only carries ids. Keep both keyed for resolution.
   103	  const toolCallsBySourceEvent = useRef(new Map<string, TrueForgeApi.ToolCall[]>());
   104	  const sessionIdRef = useRef<string | null>(null);
   105	  const activeStream = useRef<AbortController | null>(null);
   106	  // A turn can end with no output of its own — after a denial, most of all —
   107	  // so the last thing the agent said stands in as the receipt.
   108	  const narration = useRef("");
   109	
   110	  const handleEvent = useCallback((event: StreamEvent) => {
   111	    if ("type" in event && event.type === "case.started") {
   112	      sessionIdRef.current = event.sessionId;
   113	      return;
   114	    }
   115	    if ("type" in event && event.type === "stream.error") {
   116	      setError(event.error);
   117	      setPhase("error");
   118	      return;
   119	    }
   120	
   121	    if (event.type === "model.message") {
   122	      if (event.toolCalls) {
   123	        toolCallsBySourceEvent.current.set(event.id, event.toolCalls);
   124	      }
   125	      const text = contentToText(event.content);
   126	      if (text) {
   127	        narration.current = text;
   128	      }
   129	    }
   130	    setTimeline((current) => applyEvent(current, event));
   131	
   132	    if (event.type === "tool.approval_required") {
   133	      const approval = extractApproval(event);
   134	      if (approval) {
   135	        const calls = approval.sourceEventId
   136	          ? toolCallsBySourceEvent.current.get(approval.sourceEventId)
   137	          : undefined;
   138	        const call = calls?.find((candidate) => candidate.id === approval.toolCallId);
   139	        setPending({ ...approval, ...(call ? describeToolCall(call) : {}) });
   140	        setPhase("awaiting");
   141	      }
   142	      return;
   143	    }
   144	
   145	    if (event.type === "turn.done") {
   146	      // A paused turn still reports done, listing the decision it is waiting
   147	      // on. Closing the case here would retire the approval card in the same
   148	      // render it was raised in, and the gate would never be seen.
   149	      if (pendingActions(event).length > 0) {
   150	        return;
   151	      }
   152	      // An errored or cancelled turn is also a turn.done. Falling through to
   153	      // the receipt would show the agent's last sentence as the outcome of a
   154	      // case that never finished.
   155	      const failure = terminalFailure(event);
   156	      if (failure) {
   157	        setPending(null);
   158	        setError(failure);
   159	        setPhase("error");
   160	        return;
   161	      }
   162	      setPending(null);
   163	      setReceipt(buildReceipt(event, narration.current));
   164	      setPhase("done");
   165	    }
   166	  }, []);
   167	
   168	  const startCase = useCallback(async () => {
   169	    const trimmed = prompt.trim();
   170	    if (!trimmed) {
   171	      return;
   172	    }
   173	    setTimeline(emptyTimeline());
   174	    setPending(null);
   175	    setReceipt(null);
   176	    setError(null);
   177	    setPhase("running");
   178	    toolCallsBySourceEvent.current.clear();
   179	    narration.current = "";
   180	
   181	    const controller = new AbortController();
   182	    activeStream.current = controller;
   183	    try {
   184	      await consumeSse(
   185	        await fetch("/api/case", {
   186	          method: "POST",
   187	          headers: { "content-type": "application/json" },
   188	          body: JSON.stringify({ prompt: trimmed }),
   189	          signal: controller.signal,
   190	        }),
   191	        handleEvent,
   192	      );
   193	    } catch (streamError) {
   194	      if (!controller.signal.aborted) {
   195	        setError(streamError instanceof Error ? streamError.message : String(streamError));
   196	        setPhase("error");
   197	      }
   198	    } finally {
   199	      if (activeStream.current === controller) {
   200	        activeStream.current = null;
   201	      }
   202	    }
   203	  }, [handleEvent, prompt]);
   204	
   205	  const decide = useCallback(
   206	    async (decision: { status: "allow" | "deny"; reason?: string }) => {
   207	      const sessionId = sessionIdRef.current;
   208	      if (!sessionId || !pending) {
   209	        return;
   210	      }
   211	      const controller = new AbortController();
   212	      activeStream.current = controller;
   213	      setDeciding(true);
   214	      // This decision is spent. The resumed turn raises its own card if it
   215	      // pauses again, and a case that reaches a pull request pauses at every
   216	      // write along the way.
   217	      setPending(null);
   218	      setPhase("running");
   219	      try {
   220	        await consumeSse(
   221	          await fetch(`/api/case/${sessionId}/approve`, {
   222	            method: "POST",
   223	            headers: { "content-type": "application/json" },
   224	            body: JSON.stringify({
   225	              threadId: pending.threadId,
   226	              toolCallId: pending.toolCallId,
   227	              ...decision,
   228	            }),
   229	            signal: controller.signal,
   230	          }),
   231	          handleEvent,
   232	        );
   233	      } catch (streamError) {
   234	        if (!controller.signal.aborted) {
   235	          setError(streamError instanceof Error ? streamError.message : String(streamError));
   236	          setPhase("error");
   237	        }
   238	      } finally {
   239	        setDeciding(false);
   240	        if (activeStream.current === controller) {
   241	          activeStream.current = null;
   242	        }
   243	      }
   244	    },
   245	    [handleEvent, pending],
   246	  );
   247	
   248	  const working = phase === "running";
   249	  const rawEntries = timeline.entries.filter(
   250	    (entry) => entry.stage === null && entry.kind === "event",
   251	  );
   252	  // Narration the agent produced before it announced any stage. It has no
   253	  // honest home on the chain, so it is shown as preamble rather than filed
   254	  // under a stage it did not claim.
   255	  const preamble = timeline.entries.filter(
   256	    (entry) => entry.stage === null && entry.kind === "message" && entry.text,
   257	  );
   258	
   259	  return (
   260	    <div className="mt-10">
   261	      <form
   262	        onSubmit={(event) => {
   263	          event.preventDefault();
